import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第四章 谁才是让别人喜欢和拥护的人？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/4第四章 谁才是让别人喜欢和拥护的人.md","filePath":"meditation/巴利文大藏经/4第四章 谁才是让别人喜欢和拥护的人.md"}'),o={name:"meditation/巴利文大藏经/4第四章 谁才是让别人喜欢和拥护的人.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第四章-谁才是让别人喜欢和拥护的人" tabindex="-1">第四章 谁才是让别人喜欢和拥护的人？ <a class="header-anchor" href="#第四章-谁才是让别人喜欢和拥护的人" aria-label="Permalink to &quot;第四章 谁才是让别人喜欢和拥护的人？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应4经/可爱经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王来到佛陀的住所，顶礼佛陀后，波斯匿王在一旁坐好，他对佛陀说：“世尊，我独自静坐的时候，心里面生起了这样的念想：「什么样的人是让大家喜欢和拥护的人？什么样的人是让大家不喜欢、厌恶的人？」</p><p>世尊，我自己是这样来回答这个问题的：世间的任何人，只要他们的身体行为做损害别人利益，伤害别人身心的等等恶行；他们的嘴巴说恶意诽谤别人，恶意咒骂别人的等等恶言；他们的内心生起伤害别人，陷害别人的等等恶念。这样的人，他们就是大家不喜欢、厌恶的人，就算他们自称：「我们是让大家喜欢的人」，然而他们的身体行为，口说言语，内心生起来的念想这些都是让大家不喜欢、厌恶的。为什么呢？因为如果将他们对别人做的这些恶行、恶言、恶念强加在他们自己的身上，让他们去承受和体验这些恶行、恶言、恶念，他们就会不喜欢、厌恶对他们施加这些恶行、恶言、恶念的人，转换一下他们行为、言语、念想的角色就可以知道他们的这些恶行、恶言、恶念是让人不喜欢、厌恶的。</p><p>世尊，同样的道理，任何的人，他们的身体行为做的是利益别人，保护别人身心不受伤害的等等善行；他们的嘴巴说的是宽慰、鼓励别人，真实赞美别人的等等善语；他们的内心生起的是利益别人，保护别人不受伤害的等等念想。这样的人就是让大家喜欢和拥护的人。就算他们自称：「我们是大家厌恶的人，我们是大家不喜欢的人」。然而他们却是让大家喜欢和拥护的人。为什么呢？因为如果将他们对别人做的这些善行、善言、善念强加在他们自己的身上，让他们去承受和体验这些善行、善言、善念，他们也会喜欢和拥护对他们施加这些善行、善言、善念的人，转换一下他们行为、言语、念想的角色就可以知道他们的这些善行、善言、善念是让人喜欢和拥护的了。”</p><p>佛陀说：“大王，正如你所说，就是这样的，大王，世间的任何人，他们的身体行为做恶行，口说恶语，内心生起恶念，他们就不是让人喜欢和拥护的人，就算他们自己说：「我们是让人喜欢和拥护的人」，然而他们仍然不是让人喜欢和拥护的人。是什么原因呢？因为当他们转换一下角色，把他们对别人做的这些恶行、恶言、恶念强加在他们自己的身上，他们就会厌恶和不喜欢对他们做出同样恶行、恶言、恶念的人。所以身体行为做恶行，口说恶语，内心生起恶念的人是让人厌恶和不喜欢的人。</p><p>大王，同样的道理，世间的任何人，他们的身体行为做善行，口说善语，内心生起善念，他们就是让人喜欢和拥护的人，就算他们自己说：「我们是让人不喜欢、厌恶的人」，然而他们仍然是让人喜欢和拥护的人。是什么原因呢？因为当他们转换一下角色，把他们对别人做的这些善行、善言、善念强加在他们自己的身上，他们也会喜欢和拥护对他们做同样善行、善言、善念的人。所以身体行为做善行，口说善语，内心生起善念的人就是让人喜欢和拥护的人。</p><p>大王，如何判断自己是否是让人喜欢和拥护的人呢？那就是身体行为不要去做恶行，口不说恶语，内心不生起恶念，不与这些恶的行为、言语、念想有什么关联，如果能够做到，自己就是让人喜欢和拥护的人。为什么呢？因为做恶行、恶言、恶念的人会伤害到别人，这些被伤害的人会报复伤害他们的人。做这些恶行、恶言、恶念的人，他们自己也会沉浸在贪欲、愤怒、不明事理的愚痴之中，所以他们无法获得安乐，他们的行为、言语、念想都会被贪欲、愤怒、愚痴牵着走，无法获得自在的解脱。</p><p>当他们死亡的时候，离开人世的时候，他们通过恶行、恶言、恶念获得的这些财物、人事，有哪一个是他们能够带走的呢？有哪一个是他们真正能够永远拥有的呢？他们死后真正能够带走的是什么呢？什么才能如影随形的在他们死后一直在他们的身边跟随他们而去呢？</p><p>大王，只有在世间的善行、善言、善念所种植下的福德，只有在世间的恶行、恶言、恶念所造下的罪业，这两者，是可以在死后带走的，这些行善事培植出来的福德，做恶事造下的罪业才是自己真正可以在死后带走的东西。世间人死后就带走这些福德和罪业离开人世，这些福德和罪业在世间人的身边如影随形，在他们死后跟随他们而去。</p><p>因此，大王，应该多做善事，为未来世积聚福德和功德，这些福德和功德的多少决定了未来世所生的类别，福德功德浅薄、罪业深重的人下堕地狱、畜生、饿鬼三恶道，他们在痛苦和烦恼中煎熬。福德功德深厚的人会上生到人道、天道，甚至于从生死的轮回中永远的解脱出来。所以大王，要尽快的在有生之年多行善事，为自己多种植福德和功德，这样才不会在未来世下堕到三恶道去受苦，这样才能让自己在未来世再次为人，或者让自己上生到天道，甚于永远从生死的轮回煎熬中解脱出来。”</p><p>这时，佛陀说偈言：</p><p>「知自可爱者，勿自连结恶。</p><p>以行恶行人，难得于安乐。</p><p>所囚于死魔，以舍生命者。</p><p>有何是彼物，彼行前取何。</p><p>功德恶之二，是人此世作。</p><p>此为彼身物，彼行而取此。</p><p>如添影之形，此二从随彼。</p><p>是故以行善，为善积未来。</p><p>功德于后世，乃人渡津头。」</p>',22)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
